<?php require 'config.php';auth('honorarios');
if(post()){$d=$_POST['desde'];$h=$_POST['hasta'];$n=0;
 $P=rows("SELECT p.id,p.honorario,(SELECT COUNT(*) FROM atenciones at JOIN turnos t ON t.id=at.turno_id JOIN agenda a ON a.id=t.agenda_id WHERE a.profesional_id=p.id AND DATE(at.fecha) BETWEEN ? AND ?) na,(SELECT COUNT(*) FROM ordenes o WHERE o.prof_id=p.id AND o.estado='realizado' AND DATE(o.fecha_real) BETWEEN ? AND ?) ns,(SELECT COALESCE(SUM(e.honorario),0) FROM ordenes o JOIN estudios e ON e.id=o.estudio_id WHERE o.prof_id=p.id AND o.estado='realizado' AND DATE(o.fecha_real) BETWEEN ? AND ?) te FROM profesionales p WHERE p.activo=1",[$d,$h,$d,$h,$d,$h]);
 foreach($P as $r)if($r['na']+$r['ns']>0){q('INSERT INTO liquidaciones(profesional_id,desde,hasta,atenciones,estudios,total)VALUES(?,?,?,?,?,?)',[$r['id'],$d,$h,$r['na'],$r['ns'],$r['na']*$r['honorario']+$r['te']]);$n++;}
 flash($n?"Liquidación generada para $n profesional(es).":'No hay atenciones registradas en el período: no hay honorarios a liquidar.',$n>0);go('honorarios.php');}
top('honorarios');?>
<h2>Liquidar honorarios</h2><form method=post class=grid><div><label>Desde</label><input type=date name=desde required></div><div><label>Hasta</label><input type=date name=hasta required></div><button>Liquidar</button></form>
<h2>Liquidaciones</h2><table><tr><th>Profesional<th>Período<th>Atenciones<th>Estudios<th>Total</tr><?php foreach(rows('SELECT l.*,p.nombre FROM liquidaciones l JOIN profesionales p ON p.id=l.profesional_id ORDER BY l.id DESC LIMIT 50') as $r)echo '<tr><td>'.h($r['nombre']).'<td>'.$r['desde'].' a '.$r['hasta'].'<td>'.$r['atenciones'].'<td>'.$r['estudios'].'<td>$'.number_format($r['total'],2,',','.');?></table><p>No incluye facturación a pacientes ni obras sociales.</p><?php bot();
